<!doctype html><html lang="es"><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;font-size:9px;color:#263238}h2{margin:0 0 8px}table{width:100%;border-collapse:collapse}th,td{border:1px solid #cfd8dc;padding:4px}th{background:#eceff1;text-align:left}.number{text-align:right}</style></head><body><h2>Reporte de productos</h2><table><thead><tr><th>Código</th><th>Código de barras</th><th>Producto</th><th>Categoría</th><th>Unidad</th><th class="number">P. compra</th><th class="number">P. venta</th><th class="number">Precio 1</th><th class="number">Precio 2</th><th class="number">Precio 3</th><th class="number">Stock</th></tr></thead><tbody>@foreach($products as $product)<tr><td>{{ $product->codigo }}</td><td>{{ $product->codigo_barras }}</td><td>{{ $product->nombre }}</td><td>{{ $product->categoriaRelacion?->nombre ?? $product->categoria }}</td><td>{{ $product->unidad }}</td><td class="number">Bs {{ number_format($product->precio_compra,2) }}</td><td class="number">Bs {{ number_format($product->precio_venta,2) }}</td><td class="number">Bs {{ number_format($product->precio_1,2) }}</td><td class="number">Bs {{ number_format($product->precio_2,2) }}</td><td class="number">Bs {{ number_format($product->precio_3,2) }}</td><td class="number">{{ $product->stock_inicial }}</td></tr>@endforeach</tbody></table></body></html>
